namespace ProjectEuler
{
    class Program
    {
        static void Main(string[] args)
        {
            // The number from Project Euler Problem 3
            long targetNumber = 600851475143;
            long result = GetLargestPrimeFactor(targetNumber);

            Console.WriteLine($"The largest prime factor of {targetNumber} is: {result}");
        }

        static long GetLargestPrimeFactor(long n)
        {
            long divisor = 2;

            // Loop until the divisor exceeds the square root of the remaining n
            while (divisor * divisor <= n)
            {
                if (n % divisor == 0)
                {
                    // Divide n by the divisor to remove this factor
                    n /= divisor;
                }
                else
                {
                    // Only increment if not divisible
                    divisor++;
                }
            }

            // Whatever is left in n is the largest prime factor
            return n;
        }
    }
}

