public class SmallestMultiple
{
    // Helper method to calculate Greatest Common Divisor
    public static long Gcd(long a, long b)
    {
        while (b != 0)
        {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    // Helper method to calculate Least Common Multiple
    public static long Lcm(long a, long b)
    {
        if (a == 0 || b == 0) return 0;
        // Divide first to prevent overflow during multiplication
        return (a / Gcd(a, b)) * b;
    }

    public static void Main(string[] args)
    {
        long result = 1;

        // Iteratively calculate LCM for numbers 1 to 20
        for (long i = 2; i <= 20; i++)
        {
            result = Lcm(result, i);
        }

        Console.WriteLine($"The smallest multiple of 1 to 20 is: {result}");
    }
}

