public class SieveOfEratosthenes
{
    public static List<int> FindPrimes(int limit)
    {
        // Step 1: Initialize boolean array
        // default value of bool is false, so we can treat 'true' as composite
        // OR initialize all to true. Here we initialize all to true for clarity.
        bool[] isPrime = new bool[limit + 1];
        for (int i = 2; i <= limit; i++)
        {
            isPrime[i] = true;
        }

        // Step 2: Iterate from 2 up to sqrt(limit)
        for (int p = 2; p * p <= limit; p++)
        {
            // If isPrime[p] is not changed, then it is a prime
            if (isPrime[p])
            {
                // Step 3: Update all multiples of p
                // Start from p*p because smaller multiples (like 2*p) 
                // have already been marked by smaller primes (like 2)
                for (int i = p * p; i <= limit; i += p)
                {
                    isPrime[i] = false;
                }
            }
        }

        // Step 4: Collect results
        List<int> primes = new List<int>();
        for (int i = 2; i <= limit; i++)
        {
            if (isPrime[i])
            {
                primes.Add(i);
            }
        }

        return primes;
    }

    public static void Main()
    {
        int n = 50;
        List<int> result = FindPrimes(n);
        Console.WriteLine($"Primes up to {n}: " + string.Join(", ", result));
    }
}

