public class LargestProduct
{
    public static long GetMaxProduct(string numString, int k)
    {
        // Input validation
        if (string.IsNullOrEmpty(numString) || k > numString.Length)
            return 0;

        long maxProduct = 0;

        // Iterate through the string, stopping when a full window of size k cannot be formed
        for (int i = 0; i <= numString.Length - k; i++)
        {
            long currentProduct = 1;

            // Calculate product of the current window of size k
            for (int j = 0; j < k; j++)
            {
                // Convert char to int (ASCII math: '5' - '0' = 5)
                int digit = numString[i + j] - '0';
                currentProduct *= digit;
            }

            // Update maximum if current is larger
            if (currentProduct > maxProduct)
            {
                maxProduct = currentProduct;
            }
        }

        return maxProduct;
    }

    public static void Main()
    {
        // Example: Finding the largest product of 4 consecutive digits
        string number = "73167176531330624919225119674426574742355349194934";
        int k = 4;

        long result = GetMaxProduct(number, k);
        Console.WriteLine($"Largest product of {k} adjacent digits is: {result}");
    }
}

