public class SumOfPrimes
{
    public static void Main(string[] args)
    {
        // Example limit based on Project Euler Problem 10
        int limit = 2000000;
        long totalSum = GetSumOfPrimes(limit);

        Console.WriteLine($"The sum of primes below {limit} is: {totalSum}");
    }

    public static long GetSumOfPrimes(int limit)
    {
        // Step 1: Initialize Sieve Array
        // isPrime[i] will be true if i is prime
        bool[] isPrime = new bool[limit];
        for (int i = 0; i < limit; i++)
        {
            isPrime[i] = true;
        }

        // 0 and 1 are not prime numbers
        isPrime[0] = false;
        isPrime[1] = false;

        // Step 2 & 3: Perform Sieve of Eratosthenes
        // We only need to check up to sqrt(limit)
        for (int p = 2; p * p < limit; p++)
        {
            // If isPrime[p] is not changed, then it is a prime
            if (isPrime[p])
            {
                // Update all multiples of p to false
                // We can start at p*p because smaller multiples have already been marked
                for (int i = p * p; i < limit; i += p)
                {
                    isPrime[i] = false;
                }
            }
        }

        // Step 4: Calculate Sum
        long sum = 0;
        for (int i = 2; i < limit; i++)
        {
            if (isPrime[i])
            {
                sum += i;
            }
        }

        return sum;
    }
}

