public class GridProductSolver
{
    public static long GetLargestProduct(int[,] grid)
    {
        int rows = grid.GetLength(0);
        int cols = grid.GetLength(1);
        long maxProduct = 0;
        int length = 4; // Length of sequence to check

        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                // 1. Horizontal (Right)
                if (c + length <= cols)
                {
                    long prod = 1;
                    for (int k = 0; k < length; k++) prod *= grid[r, c + k];
                    if (prod > maxProduct) maxProduct = prod;
                }

                // 2. Vertical (Down)
                if (r + length <= rows)
                {
                    long prod = 1;
                    for (int k = 0; k < length; k++) prod *= grid[r + k, c];
                    if (prod > maxProduct) maxProduct = prod;
                }

                // 3. Diagonal (Down-Right)
                if (r + length <= rows && c + length <= cols)
                {
                    long prod = 1;
                    for (int k = 0; k < length; k++) prod *= grid[r + k, c + k];
                    if (prod > maxProduct) maxProduct = prod;
                }

                // 4. Anti-Diagonal (Down-Left)
                if (r + length <= rows && c - length + 1 >= 0)
                {
                    long prod = 1;
                    for (int k = 0; k < length; k++) prod *= grid[r + k, c - k];
                    if (prod > maxProduct) maxProduct = prod;
                }
            }
        }
        return maxProduct;
    }
}

