public class TriangularNumberSolver
{
    public static void Main(string[] args)
    {
        int targetDivisors = 500;
        long triangleNumber = 0;
        int n = 1;

        while (true)
        {
            // Generate the next triangle number
            triangleNumber += n;
            n++;

            // Check divisor count
            if (GetDivisorCount(triangleNumber) > targetDivisors)
            {
                Console.WriteLine($"Result: {triangleNumber}");
                break;
            }
        }
    }

    // Optimized method to count divisors in O(sqrt(num))
    private static int GetDivisorCount(long number)
    {
        int count = 0;
        int sqrt = (int)Math.Sqrt(number);

        for (int i = 1; i <= sqrt; i++)
        {
            if (number % i == 0)
            {
                // If i is a divisor, add 2 (for i and number/i)
                count += 2;
            }
        }

        // Correction: If number is a perfect square, we counted the root twice
        if (sqrt * sqrt == number)
        {
            count--;
        }

        return count;
    }
}

