public class LatticePaths
{
    public static void Main()
    {
        int gridSize = 20;
        long result = CountRoutes(gridSize);
        Console.WriteLine($"Routes in a {gridSize}x{gridSize} grid: {result}");
    }

    public static long CountRoutes(int n)
    {
        // We need an (n+1) x (n+1) array because we are counting vertices (intersections),
        // not the squares themselves. A 20x20 grid has 21x21 intersections.
        long[,] grid = new long[n + 1, n + 1];

        // Initialize boundary conditions
        for (int i = 0; i <= n; i++)
        {
            grid[i, 0] = 1; // Top row (if viewing i as x) or Left col
            grid[0, i] = 1; // Left col (if viewing i as y) or Top row
        }

        // Fill the grid using Dynamic Programming
        for (int i = 1; i <= n; i++)
        {
            for (int j = 1; j <= n; j++)
            {
                // The number of paths to point (i,j) is the sum of paths
                // from the point directly above (i-1, j) and directly left (i, j-1)
                grid[i, j] = grid[i - 1, j] + grid[i, j - 1];
            }
        }

        // The bottom-right corner contains the total count
        return grid[n, n];
    }
}

