public class NumberToWords
{
    public static void Main(string[] args)
    {
        // Test cases
        Console.WriteLine(Convert(5));     // five
        Console.WriteLine(Convert(21));    // twenty one
        Console.WriteLine(Convert(115));   // one hundred and fifteen
        Console.WriteLine(Convert(342));   // three hundred and forty two
        Console.WriteLine(Convert(1000));  // one thousand
    }

    public static string Convert(int n)
    {
        if (n < 1 || n > 1000)
            return "Number out of range";

        if (n == 1000)
            return "one thousand";

        // Arrays for lookup. Index matches the number value.
        string[] unitsMap = { "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen" };
        string[] tensMap = { "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety" };

        string words = "";

        // Handle Hundreds
        if (n >= 100)
        {
            words += unitsMap[n / 100] + " hundred";
            n %= 100;

            // Add 'and' if there are remaining numbers
            if (n > 0)
                words += " and ";
        }

        // Handle Tens and Units
        if (n > 0)
        {
            if (n < 20)
            {
                // Direct mapping for 1-19
                words += unitsMap[n];
            }
            else
            {
                // 20-99
                words += tensMap[n / 10];
                if ((n % 10) > 0)
                {
                    words += " " + unitsMap[n % 10];
                }
            }
        }

        return words;
    }
}

