namespace GeometryUtils
{
    public class CircleCheck
    {
        /// <summary>
        /// Checks if a point is inside or on the boundary of a circle.
        /// </summary>
        /// <param name="cx">Circle center X coordinate</param>
        /// <param name="cy">Circle center Y coordinate</param>
        /// <param name="radius">Radius of the circle</param>
        /// <param name="px">Point X coordinate</param>
        /// <param name="py">Point Y coordinate</param>
        /// <returns>True if inside, False otherwise</returns>
        public static bool IsPointInside(double cx, double cy, double radius, double px, double py)
        {
            // Calculate the differences in coordinates
            double dx = px - cx;
            double dy = py - cy;

            // Calculate distance squared: (x - h)^2 + (y - k)^2
            // We use squared distance to avoid the computationally expensive Math.Sqrt()
            double distanceSquared = (dx * dx) + (dy * dy);

            // Calculate radius squared
            double radiusSquared = radius * radius;

            // Check condition: distance^2 <= radius^2
            return distanceSquared <= radiusSquared;
        }

        public static void Main(string[] args)
        {
            // Example Case: Center(0,0), Radius 5, Point(3,4)
            // Distance is sqrt(3^2 + 4^2) = 5. Point is exactly on the edge.
            double cx = 0, cy = 0, r = 5;
            double px = 3, py = 4;

            if (IsPointInside(cx, cy, r, px, py))
            {
                Console.WriteLine($"Point ({px}, {py}) is inside the circle.");
            }
            else
            {
                Console.WriteLine($"Point ({px}, {py}) is outside the circle.");
            }
        }
    }
}

