public class ArrayJoiner
{
    public static string JoinStrings(string[] items, string separator)
    {
        // Handle edge cases
        if (items == null || items.Length == 0)
        {
            return string.Empty;
        }

        // Use StringBuilder for efficient string manipulation
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < items.Length; i++)
        {
            // Append the current item
            sb.Append(items[i]);

            // Append separator only if it is NOT the last item
            if (i < items.Length - 1)
            {
                sb.Append(separator);
            }
        }

        return sb.ToString();
    }

    public static void Main(string[] args)
    {
        string[] words = { "Apple", "Banana", "Cherry" };
        string result = JoinStrings(words, ", ");
        Console.WriteLine(result); // Output: Apple, Banana, Cherry
    }
}

