public class Program
{
    public static int FindMax(int[] numbers)
    {
        // Check for edge cases: null or empty array
        if (numbers == null || numbers.Length == 0)
        {
            throw new ArgumentException("Array cannot be empty or null.");
        }

        // Assume the first element is the maximum
        int max = numbers[0];

        // Iterate through the rest of the array
        for (int i = 1; i < numbers.Length; i++)
        {
            // If we find a number larger than our current max, update max
            if (numbers[i] > max)
            {
                max = numbers[i];
            }
        }

        return max;
    }

    public static void Main()
    {
        int[] data = { 10, 5, 20, 8, 15 };
        try 
        {
            int result = FindMax(data);
            Console.WriteLine("The maximum value is: " + result);
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
    }
