public class MatrixStats
{
    public static void Main(string[] args)
    {
        // Initialize a sample 3x3 matrix
        int[,] matrix = {
            { 12, 5, -2 },
            { 8, 25, 4 },
            { 6, 9, 0 }
        };

        // Get dimensions
        int rows = matrix.GetLength(0);
        int cols = matrix.GetLength(1);
        int totalElements = rows * cols;

        // Initialize stats variables
        // Important: Init min/max to the first element, not 0
        int sum = 0;
        int min = matrix[0, 0];
        int max = matrix[0, 0];

        // Nested loops to traverse the 2D array
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                int currentVal = matrix[i, j];

                // Accumulate sum
                sum += currentVal;

                // Check for new minimum
                if (currentVal < min)
                {
                    min = currentVal;
                }

                // Check for new maximum
                if (currentVal > max)
                {
                    max = currentVal;
                }
            }
        }

        // Calculate average (cast to double to preserve decimal points)
        double average = (double)sum / totalElements;

        // Output results
        Console.WriteLine("Matrix Statistics:");
        Console.WriteLine($"Sum: {sum}");
        Console.WriteLine($"Average: {average:F2}");
        Console.WriteLine($"Minimum: {min}");
        Console.WriteLine($"Maximum: {max}");
    }
}

