public class ArraySumRecursive
{
    public static void Main(string[] args)
    {
        int[] numbers = { 1, 2, 3, 4, 5 };
        int n = numbers.Length;

        int sum = FindSum(numbers, n);

        Console.WriteLine($"The sum of the array is: {sum}");
    }

    // Recursive function to find sum of array
    // arr: the array of integers
    // n: the number of elements to consider (index + 1)
    public static int FindSum(int[] arr, int n)
    {
        // Base case: if no elements are left, return 0
        if (n <= 0)
            return 0;

        // Recursive step: Add the current element (at index n-1)
        // to the sum of the remaining elements (n-1)
        return (FindSum(arr, n - 1) + arr[n - 1]);
    }
}

