public class RecursiveMax
{
    public static void Main(string[] args)
    {
        int[] numbers = { 10, 32, 4, 98, 23, 5 };

        // Start the recursion from the first index (0)
        int maxVal = FindMax(numbers, 0);

        Console.WriteLine("The maximum value is: " + maxVal);
    }

    public static int FindMax(int[] arr, int index)
    {
        // Base Case: If we are at the last element, return it
        if (index == arr.Length - 1)
        {
            return arr[index];
        }

        // Recursive Step: Get the max of the rest of the array
        int maxOfRest = FindMax(arr, index + 1);

        // Comparison logic
        if (arr[index] > maxOfRest)
        {
            return arr[index];
        }
        else
        {
            return maxOfRest;
        }
    }
}

using System;

public class BinarySearchSolver
{
    // Iterative Implementation
    public static int BinarySearchIterative(int[] arr, int target)
    {
        int min = 0;
        int max = arr.Length - 1;

        while (min <= max)
        {
            // Calculate mid to avoid potential integer overflow with (min+max)
            int mid = min + (max - min) / 2;

            if (arr[mid] == target)
            {
                return mid;
            }
            else if (arr[mid] < target)
            {
                // Target is in the right half
                min = mid + 1;
            }
            else
            {
                // Target is in the left half
                max = mid - 1;
            }
        }

        return -1; // Not found
    }

    // Recursive Implementation
    public static int BinarySearchRecursive(int[] arr, int target, int min, int max)
    {
        // Base case: search space is empty
        if (min > max)
        {
            return -1;
        }

        int mid = min + (max - min) / 2;

        if (arr[mid] == target)
        {
            return mid;
        }
        else if (arr[mid] < target)
        {
            // Recurse on the right half
            return BinarySearchRecursive(arr, target, mid + 1, max);
        }
        else
        {
            // Recurse on the left half
            return BinarySearchRecursive(arr, target, min, mid - 1);
        }
    }

    public static void Main(string[] args)
    {
        int[] sortedArray = { 2, 5, 8, 12, 16, 23, 38, 56, 72, 91 };
        int target = 23;

        Console.WriteLine("Searching for " + target + " in array...");

        // Test Iterative
        int resultIter = BinarySearchIterative(sortedArray, target);
        Console.WriteLine($"Iterative Result Index: {resultIter}");

        // Test Recursive
        int resultRec = BinarySearchRecursive(sortedArray, target, 0, sortedArray.Length - 1);
        Console.WriteLine($"Recursive Result Index: {resultRec}");
    }
}

using System;

public class Program
{
    public static void BubbleSort(int[] arr)
    {
        int n = arr.Length;
        bool swapped;

        // Outer loop for the number of passes
        for (int i = 0; i < n - 1; i++)
        {
            swapped = false;

            // Inner loop for comparison and swapping
            // Last i elements are already in place
            for (int j = 0; j < n - i - 1; j++)
            {
                if (arr[j] > arr[j + 1])
                {
                    // Swap arr[j] and arr[j+1]
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;

                    swapped = true;
                }
            }

            // If no two elements were swapped by inner loop, then break
            if (!swapped)
                break;
        }
    }

    public static void Main()
    {
        int[] data = { 64, 34, 25, 12, 22, 11, 90 };
        Console.WriteLine("Original: " + string.Join(", ", data));

        BubbleSort(data);

        Console.WriteLine("Sorted:   " + string.Join(", ", data));
    }
}

using System;

public class StringComparison
{
    public static void Main()
    {
        string s1 = "Apple";
        string s2 = "Apricot";

        int result = CustomCompare(s1, s2);

        if (result < 0)
            Console.WriteLine($"{s1} comes before {s2}");
        else if (result > 0)
            Console.WriteLine($"{s1} comes after {s2}");
        else
            Console.WriteLine("The strings are equal");
    }

    /// <summary>
    /// Compares two strings lexicographically.
    /// Returns < 0 if s1 < s2
    /// Returns > 0 if s1 > s2
    /// Returns 0 if s1 == s2
    /// </summary>
    public static int CustomCompare(string s1, string s2)
    {
        // Handle null edge cases
        if (s1 == s2) return 0;
        if (s1 == null) return -1;
        if (s2 == null) return 1;

        int len1 = s1.Length;
        int len2 = s2.Length;
        int minLength = Math.Min(len1, len2);

        // Iterate char by char
        for (int i = 0; i < minLength; i++)
        {
            if (s1[i] != s2[i])
            {
                // Return the difference in ASCII values
                return s1[i] - s2[i];
            }
        }

        // If one string is a prefix of the other, the length determines the order
        return len1 - len2;
    }
}

using System;

public class SelectionSort
{
    public static void Sort(int[] arr)
    {
        int n = arr.Length;

        // One by one move boundary of unsorted subarray
        for (int i = 0; i < n - 1; i++)
        {
            // Find the minimum element in unsorted array
            int min_idx = i;
            for (int j = i + 1; j < n; j++)
            {
                if (arr[j] < arr[min_idx])
                {
                    min_idx = j;
                }
            }

            // Swap the found minimum element with the first element
            int temp = arr[min_idx];
            arr[min_idx] = arr[i];
            arr[i] = temp;
        }
    }

    public static void Main(string[] args)
    {
        int[] arr = { 64, 25, 12, 22, 11 };
        Console.WriteLine("Original array: " + string.Join(", ", arr));

        Sort(arr);

        Console.WriteLine("Sorted array: " + string.Join(", ", arr));
    }
}

