public class Program
{
    public static void Main()
    {
        // Input text
        string text = "This is a test. That is not a test. This is only a test.";

        // separators to split by (punctuation and whitespace)
        char[] delimiters = new char[] { ' ', '.', ',', ';', '!', '?' };

        // LINQ Query
        var wordStats = text
            .ToLower() // Normalize to lowercase
            .Split(delimiters, StringSplitOptions.RemoveEmptyEntries) // Split into words
            .GroupBy(word => word) // Group by the word itself
            .Select(group => new 
            { 
                Word = group.Key, 
                Count = group.Count() 
            })
            .OrderByDescending(x => x.Count); // Sort by frequency

        // Output results
        Console.WriteLine("Word Frequencies:");
        foreach (var item in wordStats)
        {
            Console.WriteLine($"{item.Word}: {item.Count}");
        }
    }
}
